class Solution {
    bool path(TreeNode* node, int target, vector<TreeNode*>& out) {
        if (!node) return false;
        out.push_back(node);
        if (node->val == target) return true;
        if (path(node->left, target, out) || path(node->right, target, out)) return true;
        out.pop_back();
        return false;
    }
public:
    int findDistance(TreeNode* root, int p, int q) {
        vector<TreeNode*> a, b;
        path(root, p, a);
        path(root, q, b);
        int common = 0;
        while (common < static_cast<int>(min(a.size(), b.size())) && a[common] == b[common]) ++common;
        return static_cast<int>(a.size() + b.size() - 2 * common);
    }
};
